// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import { BrandTile, BrandText } from "@/blocks/sidebar-shared/sidebar-brand";
import { appNav, appProjects, appSecondary, appUser } from "@/blocks/sidebar-shared/sidebar-data";
import { NavMainFolds, NavProjects, NavSecondary } from "@/blocks/sidebar-shared/sidebar-nav-app";
import { NavUser } from "@/blocks/sidebar-shared/sidebar-user-menu";
import { Sidebar, SidebarContent, SidebarFooter, SidebarHeader, SidebarMenu, SidebarMenuButton, SidebarMenuItem } from "@/components/ui/sidebar";
import { cn } from "@/lib/utils";
export const AppSidebar = defineUi<UI.ComponentProps<typeof Sidebar> & {
  contained?: boolean;
}>("AppSidebar", ["contained", "class"], (_props, {
  slots: _slots
}) => {
  const contained = computed(() => _props["contained"] === undefined ? false : _props["contained"]);
  const className = computed(() => _props["class"]);
  const props = computed(() => omitProps(_props, ["contained", "class"]));
  return () => {
    return <Sidebar role="navigation" aria-label="Studio" class={cn("top-(--header-height)", contained.value ? "h-[calc(100%-var(--header-height))]!" as const : "h-[calc(100svh-var(--header-height))]!" as const, className.value)} {...domProps(props.value)}>
      <SidebarHeader>
        <SidebarMenu>
          <SidebarMenuItem>
            <SidebarMenuButton size="lg" asChild>
              <a href="#studio">
                <BrandTile icon="book-open" />
                <BrandText title="Looseleaf Studio" subtitle="Notebook" />
              </a>
            </SidebarMenuButton>
          </SidebarMenuItem>
        </SidebarMenu>
      </SidebarHeader>
      <SidebarContent>
        <NavMainFolds items={appNav} />
        <NavProjects projects={appProjects} />
        <NavSecondary items={appSecondary} small class="mt-auto" />
      </SidebarContent>
      <SidebarFooter>
        <NavUser user={appUser} />
      </SidebarFooter>
    </Sidebar>;
  };
});

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import { docsTrail } from "@/blocks/sidebar-shared/sidebar-data";
import { SearchForm } from "@/blocks/sidebar-shared/sidebar-search-form";
import { Breadcrumb, BreadcrumbItem, BreadcrumbLink, BreadcrumbList, BreadcrumbPage, BreadcrumbSeparator } from "@/components/ui/breadcrumb";
import { Separator } from "@/components/ui/separator";
import { SidebarTrigger } from "@/components/ui/sidebar";
const STRIP = "ll-paper ll-stock-paper ll-tooth-cold [--ll-sheet-shadow:var(--ll-shadow-hair)]";
export const SiteHeader = defineUi<{}>("SiteHeader", [], (_props, {
  slots: _slots
}) => {
  return () => {
    return <header data-slot="site-header" class={`sticky top-0 z-50 flex w-full items-center ${STRIP}`}>
      <div class="relative flex h-(--header-height) w-full items-center gap-2 px-4">
        <SidebarTrigger class="size-8" />
        <Separator orientation="vertical" class="me-2 data-[orientation=vertical]:h-4" />
        <Breadcrumb class="hidden sm:block">
          <BreadcrumbList>
            <BreadcrumbItem>
              <BreadcrumbLink href="#writing-on-paper">{docsTrail[0]}</BreadcrumbLink>
            </BreadcrumbItem>
            <BreadcrumbSeparator />
            <BreadcrumbItem>
              <BreadcrumbPage>{docsTrail[1]}</BreadcrumbPage>
            </BreadcrumbItem>
          </BreadcrumbList>
        </Breadcrumb>
        <SearchForm variant="bar" placeholder="Type to search..." class="w-full sm:ms-auto sm:w-auto" />
        <Separator class="absolute inset-x-0 bottom-0 w-auto" />
      </div>
    </header>;
  };
});

// 从上游固定版本迁移为原生 Vue 组件；保留绘制参数与 CSS，并将派生状态转换为 computed。
import * as UI from "@/lib/types";
import { defineUi, omitProps, domProps, elementRef, jsxTag } from "@/lib/component";
import { createContext, useContext, watchDependencies, stateSetter, initialState, readSlot, renderValue, useExternalStore, useImperativeHandle, useLooseleafDirection, Suspense, lazy as vueLazy, memo as vueMemo, startTransition as vueStartTransition } from "@/lib/composables";
import { Children, cloneElement, createElement, isValidElement } from "@/lib/vnode";
import { cssStyle } from "@/lib/css";
import { computed } from "vue";
import { AppSidebar } from "@/blocks/sidebar-16/components/sidebar-16-app-sidebar";
import { SiteHeader } from "@/blocks/sidebar-16/components/sidebar-16-site-header";
import { containedClasses } from "@/blocks/sidebar-shared/sidebar-contained";
import { PageBody, PageNote, PageSheet } from "@/blocks/sidebar-shared/sidebar-page";
import { SidebarProvider } from "@/components/ui/sidebar";
import { cn } from "@/lib/utils";
const Page = defineUi<{
  contained?: boolean;
}>("Page", ["contained"], (_props, {
  slots: _slots
}) => {
  const contained = computed(() => _props["contained"] === undefined ? false : _props["contained"]);
  const c = computed(() => containedClasses(contained.value));
  return () => {
    return <div class={cn("[--header-height:calc(--spacing(14))]", contained.value && "h-full")}>
      <SidebarProvider class={cn("flex-col overflow-x-clip", c.value.provider)}>
        <SiteHeader />
        <div class="flex min-h-0 flex-1">
          <AppSidebar contained={contained.value} />
          <PageSheet class={c.value.inset}>
            <PageBody title="Margins" kicker="Writing on paper">
              <PageNote title="Header on top, pad below" pose="wave">
                The strip across the top belongs to the whole window, so the search box is always in reach, wherever you have scrolled to.
              </PageNote>
            </PageBody>
          </PageSheet>
        </div>
      </SidebarProvider>
    </div>;
  };
});
export default Page;
